/* UI-independent layout changes. Keeps all generated detector coordinates consistent. */
import {makeLanePucks,moveLaneReference,distanceM,offsetPath,pointAlong,bearingDeg,laneCrossSection} from './geometry.js';
export function regeneratePucks(project,siteId){const j=project.intersections.find(j=>j.id===siteId);const old=project.devices.filter(d=>d.intersection_id===siteId&&d.role==='sensor');project.devices=project.devices.filter(d=>d.intersection_id!==siteId||d.role!=='sensor');project.devices.push(...makeLanePucks(j,old));project.communications.provisioning_state='planning';return project;}
export function movePuckAndLane(project,id,latitude,longitude){const d=project.devices.find(d=>d.id===id);if(!d)throw Error('Unknown device.');const j=project.intersections.find(j=>j.id===d.intersection_id),lane=j.lanes.find(l=>l.id===d.lane_id);if(d.role==='sensor'&&lane?.path){const dy=latitude-d.latitude,dx=longitude-d.longitude;lane.path=lane.path.map(p=>[p[0]+dy,p[1]+dx]);lane.reference=lane.path[0];lane.reference_status='Operator-aligned lane reference; verify on site.';delete lane.border_alignment;regeneratePucks(project,j.id);}else{d.latitude=latitude;d.longitude=longitude;d.location_status='provisional';if(d.role==='controller')d.mounting='roadside-cabinet-proposed';d.commissioning={state:'planned',transport:'simulated'};}return project;}
export function editLaneReference(project,siteId,laneId,{latitude,longitude,bearing,downstreamOffset,lateralShift=0}){const j=project.intersections.find(j=>j.id===siteId),index=j.lanes.findIndex(l=>l.id===laneId);if(index<0)throw Error('Unknown lane.');if(!Number.isFinite(lateralShift)||Math.abs(lateralShift)>10)throw Error('Use a lateral adjustment between −10 m and +10 m.');const lane=moveLaneReference(j.lanes[index],latitude,longitude,bearing);delete lane.border_alignment;if(lateralShift){lane.path=offsetPath(lane.path,lateralShift);lane.reference=lane.path[0];lane.lateral_offset_m+=lateralShift;lane.reference_status='Operator-adjusted vehicle-path centre; verify on site.';}j.lanes[index]=lane;j.downstream_offset_m=downstreamOffset;return regeneratePucks(project,siteId);}
export function addParallelLane(project,siteId,baseId,delta){const j=project.intersections.find(j=>j.id===siteId),base=j.lanes.find(l=>l.id===baseId);if(!base?.path)throw Error('Choose a road-aligned base lane.');const next=Math.max(0,...j.lanes.filter(l=>l.arm_id===base.arm_id&&l.flow===base.flow).map(l=>l.lane_number))+1;const lane=structuredClone(base);delete lane.border_alignment;lane.id=base.id.replace(/-L\d+$/,`-L${next}`);lane.lane_number=next;lane.path=offsetPath(base.path,delta);lane.reference=lane.path[0];if(j.lanes.some(l=>l.path&&distanceM(l.path[0],lane.path[0])<.3))throw Error('This shift overlaps an existing lane. Choose the outermost lane or a larger shift.');lane.lateral_offset_m+=delta;lane.reference_status='Operator-added parallel lane; verify lane count and centerline.';j.lanes.push(lane);regeneratePucks(project,siteId);return lane;}
export function translateSiteGeometry(j,dy,dx){for(const lane of j.lanes||[])if(lane.path){lane.path=lane.path.map(p=>[p[0]+dy,p[1]+dx]);lane.reference=lane.path[0];lane.reference_status='Site reference moved; recheck road alignment.';delete lane.border_alignment;}}
export function detectorCoverage(project,j){const sensors=project.devices.filter(d=>d.role==='sensor'&&d.intersection_id===j.id);return {inbound_lanes:j.lanes.filter(l=>l.flow==='inbound').length,outbound_lanes:j.lanes.filter(l=>l.flow==='outbound').length,upstream:sensors.filter(d=>d.placement==='upstream').length,downstream:sensors.filter(d=>d.placement==='downstream').length};}
export function boundaryTotals(project,site){const j=project.intersections.find(j=>j.id===site.id);const input=project.devices.filter(d=>d.intersection_id===site.id&&d.placement==='upstream'&&d.offset_m===60),output=project.devices.filter(d=>d.intersection_id===site.id&&d.placement==='downstream');const counts=site.device_counts;const reported=counts&&input.length&&output.length&&[...input,...output].every(d=>Number.isFinite(counts[d.id]));if(!reported)return {reported:false,inflow:null,outflow:null,stored:null,residual:null};const inflow=input.reduce((s,d)=>s+counts[d.id],0),outflow=output.reduce((s,d)=>s+counts[d.id],0),stored=Object.values(site.queues).reduce((s,v)=>s+v,0);return {reported:true,inflow,outflow,stored,residual:inflow-outflow-stored};}

// Two observed borders at the selected detector station anchor the actual lane row.
export function alignLaneBetweenBorders(project,deviceId,first,second){
 const d=project.devices.find(d=>d.id===deviceId),j=project.intersections.find(j=>j.id===d?.intersection_id),lane=j?.lanes.find(l=>l.id===d?.lane_id);
 if(d?.role!=='sensor'||!lane?.path)throw Error('Choose a lane detector first.');
 for(const p of [first,second])if(!Array.isArray(p)||p.length!==2||!p.every(Number.isFinite)||Math.abs(p[0])>90||Math.abs(p[1])>180)throw Error('Use valid coordinates for both lane borders.');
 const width=distanceM(first,second);if(width<1.8||width>6)throw Error('The two borders must be 1.8–6 m apart. Select the opposite edges of one lane.');
 const band=laneCrossSection(lane,d.offset_m),angle=(bearingDeg([first,second])-bearingDeg([band.left,band.right]))*Math.PI/180;
 if(Math.abs(Math.cos(angle))<.94)throw Error('Pick opposite borders across the lane at the same detector station.');
 const center=[(first[0]+second[0])/2,(first[1]+second[1])/2],old=pointAlong(lane.path,d.offset_m),dy=center[0]-old[0],dx=center[1]-old[1];
 lane.path=lane.path.map(p=>[p[0]+dy,p[1]+dx]);lane.reference=lane.path[0];lane.lane_width_m=width;lane.reference_status='Midpoint of two operator-picked lane borders on imagery; survey required.';
 lane.border_alignment={station_m:d.offset_m,points:[first,second].map(p=>[...p]),source:'operator imagery picks',status:'unsurveyed'};
 return regeneratePucks(project,j.id);
}
